def histogram(test: str) -> dict:
    # Split on whitespace and filter out any empty strings
    words = [w for w in test.split() if w]

    # If there are no words, return an empty dict
    if not words:
        return {}

    # Count occurrences of each word
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1

    # Find the maximum frequency
    max_freq = max(counts.values())

    # Return a dict of only the words that have the maximum frequency
    return {word: max_freq for word, freq in counts.items() if freq == max_freq}
